import java.lang.reflect.*;import java.util.*;
public class CraftStatusProbe{
 public static void main(String[]args)throws Exception{
  RecipeLoadProbe.main(new String[]{args[0]});Class<?> u=Class.forName("sun.misc.Unsafe");Field uf=u.getDeclaredField("theUnsafe");uf.setAccessible(true);Method allocate=u.getMethod("allocateInstance",Class.class);
  Class<?> rc=Class.forName("zombie.scripting.entity.components.crafting.CraftRecipe"),mc=Class.forName("zombie.scripting.objects.ScriptModule"),isc=Class.forName("zombie.scripting.entity.components.crafting.InputScript"),ic=Class.forName("zombie.inventory.InventoryItem"),fc=Class.forName("zombie.inventory.types.Food"),character=Class.forName("zombie.characters.IsoGameCharacter");
  Field mod=Class.forName("zombie.scripting.ScriptManager").getDeclaredField("currentLoadFileMod");mod.setAccessible(true);mod.set(null,"pz-vanilla");Object module=mc.getConstructor().newInstance();mc.getField("name").set(module,"Base");Object recipe=rc.getConstructor().newInstance();rc.getMethod("setModule",mc).invoke(recipe,module);rc.getMethod("InitLoadPP",String.class).invoke(recipe,"Fixture");Method load=isc.getDeclaredMethod("Load",rc,String.class);load.setAccessible(true);
  String[] suffixes={""," mode:keep"," flags[AllowFavorite]"," flags[AllowRottenItem]"," flags[AllowFrozenItem]"," flags[AllowDestroyedItem]"," flags[AllowFavorite;AllowRottenItem;AllowFrozenItem;AllowDestroyedItem]"," flags[IsDamaged]"," flags[IsUndamaged]"," flags[IsDamaged;IsUndamaged]"," flags[IsCookedFoodItem]"," flags[IsUncookedFoodItem]"," flags[IsCookedFoodItem;IsUncookedFoodItem]"};
  for(boolean food:new boolean[]{false,true})for(int mask=0;mask<64;mask++)for(String suffix:suffixes){
   String line="item 1 [Base.Fixture]"+suffix;Object input=load.invoke(null,recipe,line),item=allocate.invoke(uf.get(null),food?fc:ic);
   ItemUseProbe.set(ic,item,"favorite",(mask&1)!=0);ItemUseProbe.set(ic,item,"broken",(mask&2)!=0);ItemUseProbe.set(ic,item,"condition",(mask&4)!=0?5:10);ItemUseProbe.set(ic,item,"conditionMax",10);ItemUseProbe.set(ic,item,"isCookable",(mask&8)!=0);
   if(food){fc.getMethod("setAge",float.class).invoke(item,(mask&16)!=0?4f:0f);fc.getMethod("setOffAgeMax",int.class).invoke(item,4);fc.getMethod("setFrozen",boolean.class).invoke(item,(mask&32)!=0);fc.getMethod("setCooked",boolean.class).invoke(item,(mask&4)!=0);fc.getMethod("setBurnt",boolean.class).invoke(item,(mask&2)!=0);}
   Map<String,Object>state=new LinkedHashMap<>();state.put("food",food);state.put("favorite",ic.getMethod("isFavorite").invoke(item));state.put("broken",ic.getMethod("isBroken").invoke(item));state.put("damaged",ic.getMethod("isDamaged").invoke(item));state.put("cookable",ic.getMethod("isCookable").invoke(item));state.put("rotten",food?fc.getMethod("isRotten").invoke(item):false);state.put("frozen",food?fc.getMethod("isFrozen").invoke(item):false);state.put("uncooked",food?fc.getMethod("isUncooked").invoke(item):false);
   Map<String,Object>row=new LinkedHashMap<>();row.put("line",line);row.put("state",state);row.put("routine",isc.getMethod("doesItemPassRoutineStatusTests",ic,character).invoke(input,item,null));row.put("damage",isc.getMethod("doesItemPassDamageStatusTests",ic).invoke(input,item));row.put("cooking",isc.getMethod("doesItemPassFoodAndCookingTests",ic).invoke(input,item));System.out.println(RecipeLoadProbe.json(row));
  }
 }
}
